def align_up(value: int, alignment: int) -> int:
    if not (0 <= value <= 255) or not (0 <= alignment <= 255) or alignment == 0:
        return -1
    if not (alignment & (alignment - 1) == 0):
        return -1
    result = ((value + alignment - 1) // alignment) * alignment
    if result > 255:
        return -1
    return result
